test("highlighting preserves code, Chinese and unsupported languages without exposing HTML", async () => {
	for (const language of [
		"typescript",
		"go",
		"unknown"
	]) {
		const code = "// 中文 :12-42\nconst value = \"<script>\";\n";
		const result = await highlightCode(code, language);
		assert.equal(result.tokens.map((line) => line.map((token) => token.content).join("")).join("\n"), code);
		assert.equal(await highlightCode(code, language), result, "bounded content cache reuses the result");
	}
});
test("registered explainers enforce ownership, containment, independent CSP and read-only service", async () => {
	const root = mkdtempSync(path.join(os.tmpdir(), "lumine-explainer-"));
	let server;
	try {
		for (const name of [
			".lumine",
			"docs/repo-wiki/assets",
			"reader"
		]) mkdirSync(path.join(root, name), { recursive: true });
		writeFileSync(path.join(root, ".lumine/root.json"), "{\"schemaVersion\":2,\"kind\":\"lumine-root\"}");
		writeFileSync(path.join(root, ".lumine/project.json"), JSON.stringify({
			schemaVersion: 2,
			workflowVersion: 2,
			repositories: [{
				id: "root",
				path: "."
			}]
		}));
		writeFileSync(path.join(root, "reader/index.html"), "<html>Reader</html>");
		writeFileSync(path.join(root, "docs/repo-wiki/overview.md"), "---\nid: overview\ntitle: Overview\nsummary: An explanation\ntype: architecture\nstatus: current\n---\n# Overview\n\nA readable explanation.");
		const registry = path.join(root, "docs/repo-wiki/assets/registry.json");
		const entry = {
			id: "impact",
			documentId: "overview",
			title: "Impact",
			text: "A change suggests affected explanations.",
			path: "impact.html"
		};
		writeFileSync(registry, JSON.stringify({
			schemaVersion: 1,
			entries: [entry]
		}));
		writeFileSync(path.join(root, "docs/repo-wiki/assets/impact.html"), "<!doctype html><html><script>document.body.dataset.ready=\"true\"<\/script></html>");
		assert.match(readExplainer(root, "overview", "impact").html, /doctype/);
		assert.throws(() => readExplainer(root, "other", "impact"), /NOT_REGISTERED/);
		server = await serveWiki(root, {
			port: 0,
			assetsRoot: path.join(root, "reader")
		});
		const response = await fetch(`${server.url}/api/explainer?document=overview&asset=impact`);
		assert.equal(response.status, 200);
		assert.equal(response.headers.get("content-security-policy"), EXPLAINER_CSP);
		assert.ok(!EXPLAINER_CSP.includes("allow-same-origin"));
		assert.match(EXPLAINER_CSP, /connect-src 'none'/);
		assert.equal((await fetch(`${server.url}/api/highlight`, { method: "POST" })).status, 405);
		assert.equal((await fetch(`${server.url}/api/highlight?language=ts&code=const%20a%3D1`)).status, 200);
		writeFileSync(registry, JSON.stringify({
			schemaVersion: 1,
			entries: [{
				...entry,
				path: "../overview.md"
			}]
		}));
		assert.throws(() => readExplainer(root, "overview", "impact"), /INVALID/);
		writeFileSync(path.join(root, "outside.html"), "outside");
		symlinkSync(path.join(root, "outside.html"), path.join(root, "docs/repo-wiki/assets/escape.html"));
		writeFileSync(registry, JSON.stringify({
			schemaVersion: 1,
			entries: [{
				...entry,
				path: "escape.html"
			}]
		}));
		assert.throws(() => readExplainer(root, "overview", "impact"), /OUTSIDE_ROOT/);
	} finally {
		await server?.close();
		rmSync(root, {
			recursive: true,
			force: true
		});
	}
});
test("opaque explainers load only verified offline font assets, without widening access to APIs", async () => {
	const root = mkdtempSync(path.join(os.tmpdir(), "lumine-explainer-fonts-"));
	let server;
	try {
		for (const name of [
			".lumine",
			"docs/repo-wiki/assets",
			"reader/fonts"
		]) mkdirSync(path.join(root, name), { recursive: true });
		writeFileSync(path.join(root, ".lumine/root.json"), "{\"schemaVersion\":2,\"kind\":\"lumine-root\"}");
		writeFileSync(path.join(root, ".lumine/project.json"), JSON.stringify({
			schemaVersion: 2,
			workflowVersion: 2,
			repositories: [{
				id: "root",
				path: "."
			}]
		}));
		writeFileSync(path.join(root, "reader/index.html"), "<html>Reader</html>");
		writeFileSync(path.join(root, "docs/repo-wiki/overview.md"), "---\nid: overview\ntitle: Overview\nsummary: An explanation\ntype: architecture\nstatus: current\n---\n# Overview\n\nA readable explanation.");
		writeFileSync(path.join(root, "docs/repo-wiki/assets/registry.json"), JSON.stringify({
			schemaVersion: 1,
			entries: [{
				id: "impact",
				documentId: "overview",
				title: "Impact",
				text: "Equivalent text.",
				path: "impact.html"
			}]
		}));
		const original = "<!doctype html><html><head><script>const head=\"</head>\";<\/script></head><body>中文知识</body></html>";
		writeFileSync(path.join(root, "docs/repo-wiki/assets/impact.html"), original);
		const fontPath = "fonts/noto-sans-sc-test-normal-EXAMPLE.woff2";
		const font = Buffer.concat([Buffer.from("wOF2"), Buffer.alloc(100)]);
		const css = `@font-face{font-family:"Noto Sans SC Variable";font-style:normal;font-weight:100 900;src:url("./${fontPath}") format("woff2-variations");unicode-range:U+4E00-9FFF}body{background:url(https://outside.invalid/private)}`;
		const assets = path.join(root, "reader");
		const publish = (stylesheet, bytes = font) => {
			writeFileSync(path.join(assets, fontPath), bytes);
			writeFileSync(path.join(assets, "reader.css"), stylesheet);
			writeFileSync(path.join(assets, "manifest.json"), JSON.stringify({
				schemaVersion: 1,
				files: {
					"reader.css": hash(stylesheet),
					[fontPath]: hash(bytes)
				}
			}));
		};
		publish(css);
		server = await serveWiki(root, {
			port: 0,
			assetsRoot: assets
		});
		const endpoint = `${server.url}/api/explainer?document=overview&asset=impact`;
		const explanation = await fetch(endpoint);
		assert.equal(explanation.status, 200);
		const result = await explanation.text();
		assert.match(result, /<script>const head="<\/head>";<\/script><style data-lumine-fonts>/);
		assert.match(result, /unicode-range:U\+4E00-9FFF/);
		assert.match(result, /font-display:swap/);
		assert.ok(!result.includes("outside.invalid"), "only font declarations are injected from the reader CSS");
		const csp = explanation.headers.get("content-security-policy");
		assert.ok(csp.includes(`font-src ${server.url}/fonts/`));
		assert.match(csp, /sandbox allow-scripts;/);
		assert.ok(!csp.includes("allow-same-origin"));
		assert.match(csp, /connect-src 'none'/);
		const allowed = await fetch(`${server.url}/${fontPath}`, { headers: { Origin: "null" } });
		assert.equal(allowed.status, 200);
		assert.equal(allowed.headers.get("access-control-allow-origin"), "null");
		assert.equal(allowed.headers.get("access-control-allow-credentials"), null);
		assert.equal(allowed.headers.get("cross-origin-resource-policy"), "cross-origin");
		assert.equal(allowed.headers.get("content-type"), "font/woff2");
		assert.deepEqual(Buffer.from(await allowed.arrayBuffer()), font);
		const head = await fetch(`${server.url}/${fontPath}`, {
			method: "HEAD",
			headers: { Origin: "null" }
		});
		assert.equal(head.status, 200);
		assert.equal(await head.text(), "");
		for (const target of [
			"/api/config",
			"/api/source?document=overview&id=secret",
			"/reader.css",
			"/index.html",
			"/fonts/noto-sans-sc-unknown.woff2",
			`/${fontPath}?ignored=1`,
			"/fonts/%2e%2e%2freader.css"
		]) {
			const rejected = await fetch(`${server.url}${target}`, { headers: { Origin: "null" } });
			assert.equal(rejected.status, 403, target);
			assert.equal(rejected.headers.get("access-control-allow-origin"), null);
		}
		assert.equal((await fetch(`${server.url}/${fontPath}`, { headers: { Origin: "https://outside.invalid" } })).status, 403);
		writeFileSync(path.join(assets, fontPath), Buffer.from("changed bytes"));
		const corrupt = await fetch(`${server.url}/${fontPath}`, { headers: { Origin: "null" } });
		assert.equal(corrupt.status, 400);
		assert.equal(corrupt.headers.get("access-control-allow-origin"), null);
		publish(css.replace("U+4E00-9FFF", "U+4E01-9FFF"));
		assert.match(await (await fetch(endpoint)).text(), /unicode-range:U\+4E01-9FFF/, "asset publication invalidates the font snapshot");
		writeFileSync(path.join(assets, "reader.css"), css + "changed");
		assert.equal((await fetch(endpoint)).status, 400, "unverified stylesheet changes fail explicitly");
		publish(css.replace(`./${fontPath}`, "https://outside.invalid/font.woff2"));
		assert.equal((await fetch(endpoint)).status, 400, "external font references never enter the sandbox policy");
		publish(css);
		const outsideFont = path.join(root, "outside.woff2");
		writeFileSync(outsideFont, font);
		rmSync(path.join(assets, fontPath));
		symlinkSync(outsideFont, path.join(assets, fontPath));
		const escaped = await fetch(`${server.url}/${fontPath}`, { headers: { Origin: "null" } });
		assert.equal(escaped.status, 400, "font paths cannot escape the shipped assets via symlinks");
		assert.equal(escaped.headers.get("access-control-allow-origin"), null);
	} finally {
		await server?.close();
		rmSync(root, {
			recursive: true,
			force: true
		});
	}
});
test("a valid large registered source remains readable when it exceeds the optional highlighting budget", async () => {
	const root = mkdtempSync(path.join(os.tmpdir(), "lumine-large-source-"));
	let service;
	try {
		for (const directory of [
			".lumine",
			"docs/repo-wiki",
			"reader"
		]) mkdirSync(path.join(root, directory), { recursive: true });
		writeFileSync(path.join(root, ".lumine/root.json"), "{\"schemaVersion\":2,\"kind\":\"lumine-root\"}");
		writeFileSync(path.join(root, ".lumine/project.json"), JSON.stringify({
			schemaVersion: 2,
			workflowVersion: 2,
			repositories: [{
				id: "root",
				path: "."
			}]
		}));
		writeFileSync(path.join(root, "reader/index.html"), "<html>Reader</html>");
		const text = JSON.stringify({ example: "x".repeat(11e4) });
		writeFileSync(path.join(root, "example.json"), text);
		writeFileSync(path.join(root, "docs/repo-wiki/example.md"), `---\n${JSON.stringify({
			id: "example",
			title: "Large evidence",
			summary: "Read the registered evidence.",
			type: "architecture",
			status: "current",
			sources: [{
				id: "source",
				repoId: "root",
				path: "example.json"
			}]
		})}\n---\n# Large evidence\n\nThe original text remains available.\n`);
		service = await serveWiki(root, {
			port: 0,
			assetsRoot: path.join(root, "reader")
		});
		const response = await fetch(`${service.url}/api/source?document=example&id=source`);
		assert.equal(response.status, 200);
		const payload = await response.json();
		assert.equal(payload.text, text);
		assert.equal(payload.startLine, 1);
		assert.equal(payload.endLine, 1);
		assert.equal(payload.highlighted, undefined);
	} finally {
		await service?.close();
		rmSync(root, {
			recursive: true,
			force: true
		});
	}
});

